package portfolio.week09;
import javafx.application.Application; import javafx.concurrent.Service; import javafx.concurrent.Task; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.VBox; import javafx.stage.Stage;
public class AsyncDemo extends Application { public void start(Stage s){ ProgressBar bar=new ProgressBar(0); Label status=new Label("Ready"); Button start=new Button("Start work"); Button cancel=new Button("Cancel"); Service<String> service=new Service<>(){ protected Task<String> createTask(){ return new Task<>(){ protected String call() throws Exception { for(int i=1;i<=10;i++){ if(isCancelled()) return "Cancelled"; Thread.sleep(150); updateProgress(i,10); updateMessage("Completed step "+i+" of 10"); } return "Done"; } }; }}; bar.progressProperty().bind(service.progressProperty()); status.textProperty().bind(service.messageProperty()); start.setOnAction(e->service.restart()); cancel.setOnAction(e->service.cancel()); VBox box=new VBox(10,start,cancel,bar,status); box.setPadding(new javafx.geometry.Insets(18)); s.setScene(new Scene(box,420,180)); s.show(); } public static void main(String[] a){launch(a);} }
